function validateTitleExists(title: string): boolean {
  return title && title.trim().length > 0;
}

function validateTitleLength(title: string): boolean {
  return title.length <= 100;
}

function validateDescriptionLength(description: string | undefined): boolean {
  return !description || description.length <= 500;
}

export function validateTodoInput(input: CreateTodoInput): boolean {
  return (
    validateTitleExists(input.title) &&
    validateTitleLength(input.title) &&
    validateDescriptionLength(input.description)
  );
}

